import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test("Upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Arrange: a vendor in status "draft" owned by the signed-in member's tenant
    const member = await apiAs("member");
    const vendorName = uniqueName("DOC-01 Vendor");
    const createResponse = await member.post("/api/vendors", {
      data: {
        name: vendorName,
        category: "services",
        contact_email: `doc01.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.test`,
      },
    });
    expect(createResponse.status()).toBe(201);
    const vendor = await createResponse.json();
    expect(vendor.status).toBe("draft");

    // Act: upload the insurance certificate as kind "insurance_certificate"
    const fileName = "insurance_certificate.txt";
    const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: fileName,
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample(fileName)),
        },
      },
    });

    // Assert: response status and document state
    expect(uploadResponse.status()).toBe(201);
    const document = await uploadResponse.json();
    expect(document.kind).toBe("insurance_certificate");
    expect(document.vendor_id).toBe(vendor.id);
    expect(document.status).toBe("processing");

    // Assert: audit event recorded for the vendor
    const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditResponse.status()).toBe(200);
    const audit = await auditResponse.json();
    const uploadedEvents = audit.items.filter(
      (event: { action: string }) => event.action === "document.uploaded",
    );
    expect(uploadedEvents.length).toBeGreaterThanOrEqual(1);
  });
});
